#include <cassert>
#include <iostream>
#include <memory>

struct Parent;
struct Child {
    static int destroyed;
    std::weak_ptr<Parent> parent;  // 관찰만 하며 부모를 살려 두지 않습니다.
    ~Child() { ++destroyed; }
};
struct Parent {
    static int destroyed;
    int id = 7;
    std::shared_ptr<Child> child;
    ~Parent() { ++destroyed; }
};
int Parent::destroyed = 0;
int Child::destroyed = 0;
int main() {
    for (int trial = 0; trial < 1000; ++trial) {
        auto parent = std::make_shared<Parent>();
        auto child = std::make_shared<Child>();
        parent->child = child;
        child->parent = parent;
        {
            // expired 확인과 raw pointer 접근을 나누지 않고 lock의 결과를 소유합니다.
            auto held = child->parent.lock();
            assert(held && held->id == 7);
        }
        parent.reset();
        assert(Parent::destroyed == trial + 1);
        assert(child->parent.expired());
        assert(!child->parent.lock());
        assert(Child::destroyed == trial);  // 외부 child가 아직 소유합니다.
        child.reset();
        assert(Child::destroyed == trial + 1);
    }
    std::cout << "1000 weak-backlink lifetimes passed\n";
}
